using UnityEditor;
using UnityEngine;
using UnityEngine.UI;

namespace YasudaHaruto.BookValidation.Editor
{
    // Initial layout only. Existing UI prefabs are never regenerated by verification.
    internal static class BookReplacementUIBuilder
    {
        internal const string Path = "Assets/YasudaHaruto/Prefabs/BookPageReplacementUI.prefab";

        internal static void Attach(GameObject validationRoot)
        {
            var asset = AssetDatabase.LoadAssetAtPath<GameObject>(Path);
            if (asset == null) asset = Build();
            var panel = validationRoot.GetComponentInChildren<BookPageReplacementPanel>(true);
            if (panel == null)
            {
                var instance = (GameObject)PrefabUtility.InstantiatePrefab(asset, validationRoot.transform);
                panel = instance.GetComponent<BookPageReplacementPanel>();
            }
            var serialized = new SerializedObject(panel);
            serialized.FindProperty("m_controller").objectReferenceValue =
                validationRoot.GetComponentInChildren<BookGameController>(true);
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        private static GameObject Build()
        {
            var root = new GameObject("PageReplacementUI", typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler), typeof(GraphicRaycaster));
            try
            {
                root.GetComponent<Canvas>().renderMode = RenderMode.ScreenSpaceOverlay;
                root.GetComponent<Canvas>().sortingOrder = 200;
                var scaler = root.GetComponent<CanvasScaler>();
                scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
                scaler.referenceResolution = new Vector2(1280, 720);
                scaler.matchWidthOrHeight = 0.5f;
                var view = root.AddComponent<BookPageReplacementPanel>();
                var overlay = Rect("Overlay", root.transform);
                Stretch(overlay, 0, 0, 0, 0);
                overlay.gameObject.AddComponent<Image>().color = new Color(0.04f, 0.06f, 0.1f, 0.72f);
                var card = Rect("Panel", overlay);
                card.anchorMin = card.anchorMax = new Vector2(0.5f, 0.5f);
                card.sizeDelta = new Vector2(760, 600);
                card.gameObject.AddComponent<Image>().color = new Color(0.985f, 0.985f, 0.99f);
                Label("Title", card, "ページがいっぱいです", 30, 28, 24, 704, 46);
                var incoming = Label("IncomingPage", card, "入手ページ", 21, 28, 79, 704, 70);
                var viewport = Rect("Viewport", card);
                Stretch(viewport, 28, 28, 167, 130);
                viewport.gameObject.AddComponent<Image>().color = Color.white;
                viewport.gameObject.AddComponent<RectMask2D>();
                var content = Rect("Rows", viewport);
                content.anchorMin = new Vector2(0, 1);
                content.anchorMax = new Vector2(1, 1);
                content.pivot = new Vector2(0.5f, 1);
                content.sizeDelta = Vector2.zero;
                var layout = content.gameObject.AddComponent<VerticalLayoutGroup>();
                layout.spacing = 8;
                layout.padding = new RectOffset(4, 4, 4, 4);
                layout.childControlHeight = true;
                layout.childControlWidth = true;
                layout.childForceExpandHeight = false;
                var fitter = content.gameObject.AddComponent<ContentSizeFitter>();
                fitter.verticalFit = ContentSizeFitter.FitMode.PreferredSize;
                var scroll = viewport.gameObject.AddComponent<ScrollRect>();
                scroll.viewport = viewport;
                scroll.content = content;
                scroll.horizontal = false;
                scroll.movementType = ScrollRect.MovementType.Clamped;
                var row = Rect("RowTemplate", card);
                row.sizeDelta = new Vector2(690, 52);
                var rowImage = row.gameObject.AddComponent<Image>();
                var rowButton = row.gameObject.AddComponent<Button>();
                rowButton.targetGraphic = rowImage;
                row.gameObject.AddComponent<LayoutElement>().preferredHeight = 52;
                var rowLabel = Label("Label", row, "ページ", 21, 16, 0, 658, 52);
                rowLabel.alignment = TextAnchor.MiddleLeft;
                var rowView = row.gameObject.AddComponent<BookPageChoiceRow>();
                var rowFields = new SerializedObject(rowView);
                Assign(rowFields, "m_label", rowLabel);
                Assign(rowFields, "m_button", rowButton);
                Assign(rowFields, "m_background", rowImage);
                rowFields.ApplyModifiedPropertiesWithoutUndo();
                row.gameObject.SetActive(false);
                var selected = Label("Selection", card, "選択中：なし", 20, 28, 482, 704, 36);
                var confirm = Button("Confirm", card, "このページと入れ替える", 28, 530, 388, new Color(0.23f, 0.43f, 0.72f), Color.white);
                var decline = Button("Decline", card, "今回は受け取らない", 432, 530, 300, new Color(0.88f, 0.9f, 0.93f), new Color(0.13f, 0.17f, 0.23f));
                var fields = new SerializedObject(view);
                Assign(fields, "m_panel", overlay.gameObject);
                Assign(fields, "m_incomingLabel", incoming);
                Assign(fields, "m_selectionLabel", selected);
                Assign(fields, "m_rowsParent", content);
                Assign(fields, "m_rowTemplate", rowView);
                Assign(fields, "m_confirmButton", confirm);
                Assign(fields, "m_declineButton", decline);
                Assign(fields, "m_scroll", scroll);
                fields.ApplyModifiedPropertiesWithoutUndo();
                return PrefabUtility.SaveAsPrefabAsset(root, Path);
            }
            finally { Object.DestroyImmediate(root); }
        }

        private static RectTransform Rect(string name, Transform parent)
        {
            var rect = new GameObject(name, typeof(RectTransform)).GetComponent<RectTransform>();
            rect.SetParent(parent, false);
            return rect;
        }

        private static void Stretch(RectTransform rect, float left, float right, float top, float bottom)
        {
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.offsetMin = new Vector2(left, bottom);
            rect.offsetMax = new Vector2(-right, -top);
        }

        private static Text Label(string name, Transform parent, string text, int size, float x, float y, float width, float height)
        {
            var rect = Rect(name, parent);
            rect.anchorMin = rect.anchorMax = new Vector2(0, 1);
            rect.pivot = new Vector2(0, 1);
            rect.anchoredPosition = new Vector2(x, -y);
            rect.sizeDelta = new Vector2(width, height);
            var label = rect.gameObject.AddComponent<Text>();
            label.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            label.text = text;
            label.fontSize = size;
            label.color = new Color(0.13f, 0.17f, 0.23f);
            label.raycastTarget = false;
            return label;
        }

        private static Button Button(string name, Transform parent, string text, float x, float y, float width, Color color, Color textColor)
        {
            var label = Label(name, parent, text, 20, x, y, width, 46);
            var rect = label.rectTransform;
            // Keep the text on its own child so the background and caption stay editable.
            var background = Rect(name + "Button", parent);
            background.anchorMin = rect.anchorMin;
            background.anchorMax = rect.anchorMax;
            background.pivot = rect.pivot;
            background.anchoredPosition = rect.anchoredPosition;
            background.sizeDelta = rect.sizeDelta;
            var image = background.gameObject.AddComponent<Image>();
            image.color = color;
            var button = background.gameObject.AddComponent<Button>();
            button.targetGraphic = image;
            rect.SetParent(background, false);
            Stretch(rect, 4, 4, 4, 4);
            label.alignment = TextAnchor.MiddleCenter;
            label.color = textColor;
            return button;
        }

        private static void Assign(SerializedObject target, string property, Object value) =>
            target.FindProperty(property).objectReferenceValue = value;
    }
}
